CREATE OR REPLACE FUNCTION fn_registrar_log_dml()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_dado_anterior JSONB;
    v_dado_atual JSONB;
    v_usuario_banco VARCHAR(255) := SESSION_USER::TEXT;
BEGIN
    IF TG_TABLE_NAME IN (
        'insere_log',
        'altera_log',
        'deleta_log'
    ) THEN
        RAISE EXCEPTION
            'A função de auditoria não pode monitorar a tabela %.',
            TG_TABLE_NAME;
    END IF;

    IF TG_OP = 'INSERT' THEN
        INSERT INTO insere_log (
            tabela,
            dado,
            usuario
        )
        VALUES (
            TG_TABLE_NAME,
            TO_JSONB(NEW),
            v_usuario_banco
        );

        RETURN NEW;

    ELSIF TG_OP = 'UPDATE' THEN
        SELECT
            COALESCE(
                JSONB_OBJECT_AGG(anterior.chave, anterior.valor),
                '{}'::JSONB
            ),
            COALESCE(
                JSONB_OBJECT_AGG(atual.chave, atual.valor),
                '{}'::JSONB
            )
        INTO
            v_dado_anterior,
            v_dado_atual
        FROM JSONB_EACH(TO_JSONB(OLD))
            AS anterior(chave, valor)
        INNER JOIN JSONB_EACH(TO_JSONB(NEW))
            AS atual(chave, valor)
            ON atual.chave = anterior.chave
        WHERE anterior.valor IS DISTINCT FROM atual.valor;

        IF v_dado_anterior <> '{}'::JSONB THEN
            INSERT INTO altera_log (
                tabela,
                dado_anterior,
                dado_atual,
                usuario
            )
            VALUES (
                TG_TABLE_NAME,
                v_dado_anterior,
                v_dado_atual,
                v_usuario_banco
            );
        END IF;

        RETURN NEW;

    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO deleta_log (
            tabela,
            dado,
            usuario
        )
        VALUES (
            TG_TABLE_NAME,
            TO_JSONB(OLD),
            v_usuario_banco
        );

        RETURN OLD;
    END IF;

    RAISE EXCEPTION
        'Operação DML não suportada pela auditoria: %.',
        TG_OP;
END;
$$;

COMMENT ON FUNCTION fn_registrar_log_dml() IS
'Função genérica acionada por triggers AFTER para auditar INSERT, UPDATE e DELETE, registrando o usuário conectado ao PostgreSQL.';

REVOKE ALL
ON FUNCTION fn_registrar_log_dml()
FROM PUBLIC;

CREATE OR REPLACE FUNCTION fn_registrar_acesso_diario(
    p_usuario_id BIGINT
)
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO acesso (
        data,
        usuario_id
    )
    VALUES (
        CURRENT_DATE,
        p_usuario_id 
    )
    ON CONFLICT (data, usuario_id)
    DO NOTHING;
END;
$$;

-- Exemplo: SELECT fn_retornar_nivel_acesso('firebase-uid');
CREATE OR REPLACE FUNCTION fn_retornar_nivel_acesso(
    p_firebase_uid TEXT
)
RETURNS TEXT
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_tipo TEXT;
BEGIN
    IF p_firebase_uid IS NULL OR BTRIM(p_firebase_uid) = '' THEN
        RETURN 'SEM_ACESSO';
    END IF;

    IF EXISTS (SELECT 1 FROM admin WHERE firebase_uid = p_firebase_uid) THEN
        RETURN 'ADMIN';
    END IF;

    SELECT tipo INTO v_tipo
    FROM usuario
    WHERE firebase_uid = p_firebase_uid;

    RETURN COALESCE(v_tipo, 'SEM_ACESSO');
END;
$$;

COMMENT ON FUNCTION fn_retornar_nivel_acesso(TEXT) IS
'Retorna ADMIN quando o Firebase UID existe em admin; caso contrário, retorna o tipo de usuario ou SEM_ACESSO. A consulta identifica o perfil independentemente do status do usuário.';

CREATE OR REPLACE FUNCTION fn_desativar_usuario_por_cargo()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE usuario
    SET status = 'DESATIVADO'
    WHERE cargo_id = NEW.id_cargo
      AND tipo <> 'GESTOR_WORKSPACE'
      AND status <> 'DESATIVADO';

    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION fn_desativar_usuario_por_cargo() IS
'Desativa usuários vinculados ao cargo desativado, preservando gestores de workspace e evitando atualizar contas já desativadas.';

CREATE OR REPLACE FUNCTION fn_desativar_usuario_por_unidade()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE usuario
    SET status = 'DESATIVADO'
    WHERE unidade_id = NEW.id_unidade
      AND tipo <> 'GESTOR_WORKSPACE'
      AND status <> 'DESATIVADO';

    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION fn_desativar_usuario_por_unidade() IS
'Desativa usuários vinculados à unidade desativada, preservando gestores de workspace e evitando atualizar contas já desativadas.';

CREATE OR REPLACE FUNCTION fn_ativar_colaborador_apos_firebase_uid()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.status := 'ATIVO';
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION fn_ativar_colaborador_apos_firebase_uid() IS
'Ativa o colaborador pré-cadastrado quando seu firebase_uid passa de nulo para preenchido.';

CREATE OR REPLACE FUNCTION fn_altera_status_cargo(
    p_firebase_uid TEXT,
    p_id_cargo BIGINT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
AS $$
DECLARE
    v_workspace_id BIGINT;
    v_ativo BOOLEAN;
BEGIN
    IF NULLIF(BTRIM(p_firebase_uid), '') IS NULL OR p_id_cargo IS NULL THEN
        RAISE EXCEPTION 'Informe um Firebase UID e um ID de cargo válidos.'
            USING ERRCODE = '22023';
    END IF;

    SELECT un.workspace_id
    INTO v_workspace_id
    FROM usuario solicitante
    INNER JOIN unidade un
        ON un.id_unidade = solicitante.unidade_id
    WHERE solicitante.firebase_uid = p_firebase_uid
      AND solicitante.tipo IN ('GESTOR', 'GESTOR_WORKSPACE')
      AND solicitante.status = 'ATIVO';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Gestor ativo não encontrado para o Firebase UID informado.'
            USING ERRCODE = '42501';
    END IF;

    UPDATE cargo
    SET ativo = NOT COALESCE(ativo, FALSE)
    WHERE id_cargo = p_id_cargo
      AND workspace_id = v_workspace_id
    RETURNING ativo INTO v_ativo;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cargo não encontrado no workspace do gestor.'
            USING ERRCODE = 'P0002';
    END IF;

    RETURN v_ativo;
END;
$$;

COMMENT ON FUNCTION fn_altera_status_cargo(TEXT, BIGINT) IS
'Alterna o status ativo do cargo informado quando o Firebase UID pertence a um gestor ativo do mesmo workspace. Retorna TRUE quando o cargo fica ativo e FALSE quando fica inativo. Ao desativar, o trigger existente desativa os usuários vinculados conforme suas regras.';

CREATE OR REPLACE FUNCTION fn_altera_cargo(
    p_firebase_uid TEXT,
    p_id_cargo BIGINT,
    p_nome TEXT,
    p_status TEXT
)
RETURNS SETOF vw_cargos
LANGUAGE plpgsql
AS $$
DECLARE
    v_workspace_id BIGINT;
    v_ativo BOOLEAN;
    v_id_cargo BIGINT;
BEGIN
    IF NULLIF(BTRIM(p_firebase_uid), '') IS NULL
       OR p_id_cargo IS NULL
       OR NULLIF(BTRIM(p_nome), '') IS NULL
       OR NULLIF(BTRIM(p_status), '') IS NULL THEN
        RAISE EXCEPTION 'Informe Firebase UID, ID do cargo, nome e status.'
            USING ERRCODE = '22023';
    END IF;

    IF CHAR_LENGTH(BTRIM(p_nome)) NOT BETWEEN 2 AND 255 THEN
        RAISE EXCEPTION 'O nome do cargo deve ter entre 2 e 255 caracteres.'
            USING ERRCODE = '22023';
    END IF;

    IF LOWER(BTRIM(p_status)) NOT IN ('ativo', 'inativo') THEN
        RAISE EXCEPTION 'O status deve ser Ativo ou Inativo.'
            USING ERRCODE = '22023';
    END IF;

    v_ativo := LOWER(BTRIM(p_status)) = 'ativo';

    SELECT un.workspace_id
    INTO v_workspace_id
    FROM usuario solicitante
    INNER JOIN unidade un
        ON un.id_unidade = solicitante.unidade_id
    WHERE solicitante.firebase_uid = p_firebase_uid
      AND solicitante.tipo IN ('GESTOR', 'GESTOR_WORKSPACE')
      AND solicitante.status = 'ATIVO';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Gestor ativo não encontrado para o Firebase UID informado.'
            USING ERRCODE = '42501';
    END IF;

    UPDATE cargo
    SET nome = BTRIM(p_nome),
        ativo = v_ativo
    WHERE id_cargo = p_id_cargo
      AND workspace_id = v_workspace_id
    RETURNING id_cargo INTO v_id_cargo;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cargo não encontrado no workspace do gestor.'
            USING ERRCODE = 'P0002';
    END IF;

    RETURN QUERY
    SELECT vc.*
    FROM vw_cargos vc
    WHERE vc.id_cargo = v_id_cargo
      AND vc.id_workspace = v_workspace_id;
END;
$$;

COMMENT ON FUNCTION fn_altera_cargo(TEXT, BIGINT, TEXT, TEXT) IS
'Atualiza nome e status de um cargo quando o Firebase UID pertence a um gestor ativo do mesmo workspace. Aceita status Ativo ou Inativo e retorna a linha atualizada de vw_cargos. Ao desativar, o trigger existente desativa os usuários vinculados conforme suas regras.';

CREATE OR REPLACE FUNCTION fn_altera_status_unidade(
    p_firebase_uid TEXT,
    p_id_unidade BIGINT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
AS $$
DECLARE
    v_workspace_id BIGINT;
    v_ativo BOOLEAN;
BEGIN
    IF NULLIF(BTRIM(p_firebase_uid), '') IS NULL OR p_id_unidade IS NULL THEN
        RAISE EXCEPTION 'Informe um Firebase UID e um ID de unidade válidos.'
            USING ERRCODE = '22023';
    END IF;

    SELECT unidade_gestor.workspace_id
    INTO v_workspace_id
    FROM usuario solicitante
    INNER JOIN unidade unidade_gestor
        ON unidade_gestor.id_unidade = solicitante.unidade_id
    WHERE solicitante.firebase_uid = p_firebase_uid
      AND solicitante.tipo IN ('GESTOR', 'GESTOR_WORKSPACE')
      AND solicitante.status = 'ATIVO';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Gestor ativo não encontrado para o Firebase UID informado.'
            USING ERRCODE = '42501';
    END IF;

    UPDATE unidade
    SET ativo = NOT COALESCE(ativo, FALSE)
    WHERE id_unidade = p_id_unidade
      AND workspace_id = v_workspace_id
    RETURNING ativo INTO v_ativo;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Unidade não encontrada no workspace do gestor.'
            USING ERRCODE = 'P0002';
    END IF;

    RETURN v_ativo;
END;
$$;

COMMENT ON FUNCTION fn_altera_status_unidade(TEXT, BIGINT) IS
'Alterna o status da unidade quando o Firebase UID pertence a um gestor ativo do mesmo workspace. Retorna TRUE quando fica ativa e FALSE quando fica inativa. Ao desativar, o trigger existente executa as regras de desativação dos usuários vinculados.';

-- Analisa a consulta das turmas e participações de um usuário.
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF, SUMMARY ON)
SELECT id_turma_colaborador, turma_id
FROM turma_colaborador
WHERE usuario_id = (SELECT MIN(usuario_id) FROM turma_colaborador)
ORDER BY turma_id;

CREATE INDEX IF NOT EXISTS idx_turma_colaborador_usuario_turma
    ON turma_colaborador (usuario_id, turma_id);

COMMENT ON INDEX idx_turma_colaborador_usuario_turma IS
'Otimiza a consulta das turmas e do histórico de treinamentos de um usuário.';

-- Analisa a consulta das evidências vinculadas a uma conclusão de evento.
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF, SUMMARY ON)
SELECT id_evidencia, nome_original, caminho_objeto, mime_type, tamanho_byte
FROM evidencia
WHERE conclusao_evento_id = (
    SELECT MIN(conclusao_evento_id)
    FROM evidencia
)
ORDER BY id_evidencia;

CREATE INDEX IF NOT EXISTS idx_evidencia_conclusao_evento
    ON evidencia (conclusao_evento_id);

COMMENT ON INDEX idx_evidencia_conclusao_evento IS
'Otimiza a consulta das evidências associadas a uma conclusão de evento.';

-- Analisa a busca reversa dos cargos associados a uma NR.
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF, SUMMARY ON)
SELECT cargo_id
FROM cargo_nr
WHERE nr_id = (SELECT MIN(nr_id) FROM cargo_nr)
ORDER BY cargo_id;

CREATE INDEX IF NOT EXISTS idx_cargo_nr_nr_cargo
    ON cargo_nr (nr_id, cargo_id);

COMMENT ON INDEX idx_cargo_nr_nr_cargo IS
'Otimiza a busca dos cargos aos quais uma Norma Regulamentadora se aplica.';

-- Analisa a busca reversa das unidades associadas a uma NR.
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF, SUMMARY ON)
SELECT unidade_id
FROM unidade_nr
WHERE nr_id = (SELECT MIN(nr_id) FROM unidade_nr)
ORDER BY unidade_id;

CREATE INDEX IF NOT EXISTS idx_unidade_nr_nr_unidade
    ON unidade_nr (nr_id, unidade_id);

COMMENT ON INDEX idx_unidade_nr_nr_unidade IS
'Otimiza a busca das unidades às quais uma Norma Regulamentadora se aplica.';

CREATE INDEX IF NOT EXISTS idx_evento_astro_criado_em
    ON public.evento_astro (criado_em DESC, id_evento DESC);

COMMENT ON INDEX public.idx_evento_astro_criado_em IS
'Otimiza a consulta dos eventos da aplicação web do Astro do mais recente para o mais antigo.';

CREATE TABLE insere_log (
    id_log BIGSERIAL,
    tabela VARCHAR(255) NOT NULL,
    data TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    dado JSONB NOT NULL,
    usuario VARCHAR(255) NOT NULL,

    CONSTRAINT pk_insere_log PRIMARY KEY (id_log),
    CONSTRAINT ck_insere_log_tabela CHECK (CHAR_LENGTH(BTRIM(tabela)) >= 1),
    CONSTRAINT ck_insere_log_usuario CHECK (CHAR_LENGTH(BTRIM(usuario)) >= 1)
);

COMMENT ON TABLE insere_log IS 'Auditoria dos registros inseridos nas tabelas monitoradas do Astro.';
COMMENT ON COLUMN insere_log.id_log IS 'Identificador interno e autoincrementado do log de inserção.';
COMMENT ON COLUMN insere_log.tabela IS 'Nome da tabela na qual o registro foi inserido.';
COMMENT ON COLUMN insere_log.data IS 'Data e horário da inserção, considerando o fuso horário da sessão.';
COMMENT ON COLUMN insere_log.dado IS 'Representação JSONB completa do registro criado.';
COMMENT ON COLUMN insere_log.usuario IS 'Usuário da conexão com o banco de dados que realizou a operação.';

CREATE TABLE altera_log (
    id_log BIGSERIAL,
    tabela VARCHAR(255) NOT NULL,
    data TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    dado_anterior JSONB NOT NULL,
    dado_atual JSONB NOT NULL,
    usuario VARCHAR(255) NOT NULL,

    CONSTRAINT pk_altera_log PRIMARY KEY (id_log),
    CONSTRAINT ck_altera_log_tabela CHECK (CHAR_LENGTH(BTRIM(tabela)) >= 1),
    CONSTRAINT ck_altera_log_usuario CHECK (CHAR_LENGTH(BTRIM(usuario)) >= 1),
    CONSTRAINT ck_altera_log_possui_alteracao CHECK (
        dado_anterior <> '{}'::JSONB AND dado_atual <> '{}'::JSONB
    )
);

COMMENT ON TABLE altera_log IS 'Auditoria dos campos efetivamente alterados nas tabelas monitoradas do Astro.';
COMMENT ON COLUMN altera_log.id_log IS 'Identificador interno e autoincrementado do log de alteração.';
COMMENT ON COLUMN altera_log.tabela IS 'Nome da tabela na qual o registro foi alterado.';
COMMENT ON COLUMN altera_log.data IS 'Data e horário da alteração, considerando o fuso horário da sessão.';
COMMENT ON COLUMN altera_log.dado_anterior IS 'JSONB contendo somente os campos alterados e seus valores anteriores.';
COMMENT ON COLUMN altera_log.dado_atual IS 'JSONB contendo somente os campos alterados e seus valores novos.';
COMMENT ON COLUMN altera_log.usuario IS 'Usuário da conexão com o banco de dados que realizou a operação.';

CREATE TABLE deleta_log (
    id_log BIGSERIAL,
    tabela VARCHAR(255) NOT NULL,
    data TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    dado JSONB NOT NULL,
    usuario VARCHAR(255) NOT NULL,

    CONSTRAINT pk_deleta_log PRIMARY KEY (id_log),
    CONSTRAINT ck_deleta_log_tabela CHECK (CHAR_LENGTH(BTRIM(tabela)) >= 1),
    CONSTRAINT ck_deleta_log_usuario CHECK (CHAR_LENGTH(BTRIM(usuario)) >= 1)
);

COMMENT ON TABLE deleta_log IS 'Auditoria dos registros excluídos das tabelas monitoradas do Astro.';
COMMENT ON COLUMN deleta_log.id_log IS 'Identificador interno e autoincrementado do log de exclusão.';
COMMENT ON COLUMN deleta_log.tabela IS 'Nome da tabela da qual o registro foi excluído.';
COMMENT ON COLUMN deleta_log.data IS 'Data e horário da exclusão, considerando o fuso horário da sessão.';
COMMENT ON COLUMN deleta_log.dado IS 'Representação JSONB completa do registro antes da exclusão.';
COMMENT ON COLUMN deleta_log.usuario IS 'Usuário da conexão com o banco de dados que realizou a operação.';

CREATE OR REPLACE PROCEDURE ler_json_nr(p_json_data text DEFAULT NULL)
LANGUAGE plpgsql
AS $$
DECLARE
    v_json jsonb;
BEGIN
    BEGIN
        v_json := p_json_data::jsonb;
    EXCEPTION WHEN others THEN
        RAISE EXCEPTION 'O parâmetro enviado não é um JSON válido.';
    END;

    IF v_json IS NULL THEN
        RAISE EXCEPTION 'O parâmetro enviado não é um JSON válido.';
    END IF;

    INSERT INTO nr_catalogo (codigo_nr, titulo, revogada, tempo_reciclagem_mes)
    SELECT
        (elem::jsonb ->> 'id')::integer                       AS codigo_nr,
        (elem::jsonb ->> 'nome')::varchar                     AS titulo,
        (elem::jsonb ->> 'revogada')::boolean                 AS revogada,
        (elem::jsonb ->> 'tempo_reciclagem_mes')::integer   AS tempo_reciclagem_mes
    FROM jsonb_array_elements_text(v_json) AS elem
    ON CONFLICT (codigo_nr)
    DO UPDATE SET
        titulo                 = EXCLUDED.titulo,
        revogada               = EXCLUDED.revogada,
        tempo_reciclagem_mes = EXCLUDED.tempo_reciclagem_mes;

END;
$$;

-- JSON esperado de exemplo:
-- [
--   {
--     "nome": "Rafael",
--     "email": "Rafael.teste@gmail.com",
--     "nr": 1,
--     "dataValidade": "2027-02-02"
--   },
--   {
--     "nome": "Lucas",
--     "email": "lucas.teste@gmail.com",
--     "nr": 5,
--     "dataValidade": "2027-03-10"
--   }
-- ]
CREATE OR REPLACE PROCEDURE inserir_conformidade_json(
    IN p_json_data TEXT,
    INOUT p_erros JSONB DEFAULT '[]'::JSONB
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_json JSONB;
    v_item JSONB;
    v_indice BIGINT;
    v_email TEXT;
    v_usuarios BIGINT[];
    v_usuario_id BIGINT;
    v_nr INTEGER;
    v_validade DATE;
    v_erro TEXT;
BEGIN
    p_erros := '[]'::JSONB;
    BEGIN
        v_json := p_json_data::JSONB;
    EXCEPTION WHEN invalid_text_representation THEN
        p_erros := JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
            'indice', NULL, 'registro', p_json_data, 'erro', 'JSON inválido.'
        ));
        RETURN;
    END;

    IF JSONB_TYPEOF(v_json) IS DISTINCT FROM 'array' THEN
        p_erros := JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
            'indice', NULL, 'registro', v_json, 'erro', 'O JSON deve ser um array de objetos.'
        ));
        RETURN;
    END IF;

    FOR v_item, v_indice IN
        SELECT value, ordinality FROM JSONB_ARRAY_ELEMENTS(v_json) WITH ORDINALITY
    LOOP
        -- O bloco isola erros de dados por item, sem desfazer os itens válidos anteriores.
        BEGIN
            IF JSONB_TYPEOF(v_item) IS DISTINCT FROM 'object' THEN
                RAISE EXCEPTION 'O item deve ser um objeto.' USING ERRCODE = '22023';
            END IF;
            IF JSONB_TYPEOF(v_item -> 'email') IS DISTINCT FROM 'string'
               OR BTRIM(v_item ->> 'email') = '' THEN
                RAISE EXCEPTION 'Informe um e-mail não vazio.' USING ERRCODE = '22023';
            END IF;
            v_email := LOWER(BTRIM(v_item ->> 'email'));

            SELECT ARRAY_AGG(id_usuario) INTO v_usuarios
            FROM usuario
            WHERE LOWER(BTRIM(email)) = v_email AND tipo = 'COLABORADOR';

            IF v_usuarios IS NULL THEN
                RAISE EXCEPTION 'Funcionário não encontrado para o e-mail informado.' USING ERRCODE = '22023';
            END IF;
            IF CARDINALITY(v_usuarios) > 1 THEN
                RAISE EXCEPTION 'E-mail ambíguo: mais de um funcionário encontrado.' USING ERRCODE = '22023';
            END IF;
            v_usuario_id := v_usuarios[1];

            IF JSONB_TYPEOF(v_item -> 'nr') IS DISTINCT FROM 'number'
               OR (v_item ->> 'nr') !~ '^[1-9][0-9]*$' THEN
                RAISE EXCEPTION 'A NR deve ser um número inteiro positivo.' USING ERRCODE = '22023';
            END IF;
            BEGIN
                v_nr := (v_item ->> 'nr')::INTEGER;
            EXCEPTION WHEN numeric_value_out_of_range THEN
                RAISE EXCEPTION 'Número da NR fora do intervalo permitido.' USING ERRCODE = '22023';
            END;
            IF NOT EXISTS (SELECT 1 FROM nr_catalogo WHERE codigo_nr = v_nr) THEN
                RAISE EXCEPTION 'NR não encontrada no catálogo.' USING ERRCODE = '22023';
            END IF;

            IF JSONB_TYPEOF(v_item -> 'dataValidade') IS DISTINCT FROM 'string'
               OR (v_item ->> 'dataValidade') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
                RAISE EXCEPTION 'Informe dataValidade no formato YYYY-MM-DD.' USING ERRCODE = '22023';
            END IF;
            BEGIN
                v_validade := (v_item ->> 'dataValidade')::DATE;
            EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
                RAISE EXCEPTION 'dataValidade não é uma data válida.' USING ERRCODE = '22023';
            END;

            -- Serializa chamadas desta procedure para o mesmo funcionário em READ COMMITTED.
            -- O esquema admite múltiplas conformidades por funcionário/NR; não há UNIQUE do par.
            PERFORM 1 FROM usuario
            WHERE id_usuario = v_usuario_id
            FOR NO KEY UPDATE;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'Funcionário não encontrado para o e-mail informado.' USING ERRCODE = '22023';
            END IF;

            UPDATE conformidade
            SET data_validade = v_validade
            WHERE usuario_id = v_usuario_id AND nr_id = v_nr;

            IF NOT FOUND THEN
                INSERT INTO conformidade
                    (usuario_id, nr_id, aplicavel, data_validade, origem, conclusao_evento_id)
                VALUES (v_usuario_id, v_nr, TRUE, v_validade, 'MANUAL', NULL);
            END IF;
        EXCEPTION
            WHEN invalid_parameter_value THEN
                GET STACKED DIAGNOSTICS v_erro = MESSAGE_TEXT;
                p_erros := p_erros || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
                    'indice', v_indice, 'registro', v_item, 'erro', v_erro
                ));
            WHEN foreign_key_violation THEN
                p_erros := p_erros || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
                    'indice', v_indice, 'registro', v_item,
                    'erro', 'Uma referência de funcionário ou NR deixou de existir durante a importação.'
                ));
        END;
    END LOOP;
END;
$$;

COMMENT ON PROCEDURE inserir_conformidade_json(TEXT, JSONB) IS
'Importa um array JSON de conformidades por e-mail e NR. Atualiza somente a validade das existentes, insere novas como MANUAL/aplicável e devolve os itens rejeitados em p_erros.';

CREATE OR REPLACE PROCEDURE pr_inseri_cargo(
    IN p_firebase_uid TEXT,
    IN p_nome TEXT,
    IN p_status TEXT
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_workspace_id BIGINT;
    v_ativo BOOLEAN;
BEGIN
    IF NULLIF(BTRIM(p_firebase_uid), '') IS NULL
       OR NULLIF(BTRIM(p_nome), '') IS NULL
       OR NULLIF(BTRIM(p_status), '') IS NULL THEN
        RAISE EXCEPTION 'Informe Firebase UID, nome e status do cargo.'
            USING ERRCODE = '22023';
    END IF;

    IF CHAR_LENGTH(BTRIM(p_nome)) NOT BETWEEN 2 AND 255 THEN
        RAISE EXCEPTION 'O nome do cargo deve ter entre 2 e 255 caracteres.'
            USING ERRCODE = '22023';
    END IF;

    IF LOWER(BTRIM(p_status)) NOT IN ('ativo', 'inativo') THEN
        RAISE EXCEPTION 'O status deve ser Ativo ou Inativo.'
            USING ERRCODE = '22023';
    END IF;

    v_ativo := LOWER(BTRIM(p_status)) = 'ativo';

    SELECT un.workspace_id
    INTO v_workspace_id
    FROM usuario solicitante
    INNER JOIN unidade un
        ON un.id_unidade = solicitante.unidade_id
    WHERE solicitante.firebase_uid = p_firebase_uid
      AND solicitante.tipo IN ('GESTOR', 'GESTOR_WORKSPACE')
      AND solicitante.status = 'ATIVO';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Gestor ativo não encontrado para o Firebase UID informado.'
            USING ERRCODE = '42501';
    END IF;

    INSERT INTO cargo (workspace_id, nome, ativo)
    VALUES (v_workspace_id, BTRIM(p_nome), v_ativo);
END;
$$;

COMMENT ON PROCEDURE pr_inseri_cargo(TEXT, TEXT, TEXT) IS
'Insere um cargo no workspace associado ao Firebase UID de um gestor ativo. Recebe o nome e o status Ativo/Inativo; o status é gravado no campo cargo.ativo.';

CREATE OR REPLACE PROCEDURE pr_alterar_cargo_nrs(
    IN p_firebase_uid TEXT,
    IN p_id_cargo BIGINT,
    IN p_nrs JSONB
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_workspace_id BIGINT;
    v_item JSONB;
    v_indice BIGINT;
    v_nr INTEGER;
    v_ativo BOOLEAN;
    v_nrs_processadas INTEGER[] := ARRAY[]::INTEGER[];
BEGIN
    IF NULLIF(BTRIM(p_firebase_uid), '') IS NULL
       OR p_id_cargo IS NULL
       OR p_nrs IS NULL THEN
        RAISE EXCEPTION 'Informe Firebase UID, ID do cargo e a lista de NRs.'
            USING ERRCODE = '22023';
    END IF;

    IF JSONB_TYPEOF(p_nrs) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'A lista de NRs deve ser um array JSON.'
            USING ERRCODE = '22023';
    END IF;

    SELECT un.workspace_id
    INTO v_workspace_id
    FROM usuario solicitante
    INNER JOIN unidade un
        ON un.id_unidade = solicitante.unidade_id
    WHERE solicitante.firebase_uid = p_firebase_uid
      AND solicitante.tipo IN ('GESTOR', 'GESTOR_WORKSPACE')
      AND solicitante.status = 'ATIVO';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Gestor ativo não encontrado para o Firebase UID informado.'
            USING ERRCODE = '42501';
    END IF;

    PERFORM 1
    FROM cargo
    WHERE id_cargo = p_id_cargo
      AND workspace_id = v_workspace_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cargo não encontrado no workspace do gestor.'
            USING ERRCODE = 'P0002';
    END IF;

    FOR v_item, v_indice IN
        SELECT elemento, posicao
        FROM JSONB_ARRAY_ELEMENTS(p_nrs) WITH ORDINALITY AS itens(elemento, posicao)
    LOOP
        IF JSONB_TYPEOF(v_item) IS DISTINCT FROM 'object' THEN
            RAISE EXCEPTION 'O item % deve ser um objeto JSON.', v_indice
                USING ERRCODE = '22023';
        END IF;

        IF JSONB_TYPEOF(v_item -> 'nr') IS DISTINCT FROM 'number'
           OR (v_item ->> 'nr') !~ '^[1-9][0-9]*$' THEN
            RAISE EXCEPTION 'O campo nr do item % deve ser um inteiro positivo.', v_indice
                USING ERRCODE = '22023';
        END IF;

        BEGIN
            v_nr := (v_item ->> 'nr')::INTEGER;
        EXCEPTION WHEN numeric_value_out_of_range THEN
            RAISE EXCEPTION 'O código NR do item % está fora do intervalo permitido.', v_indice
                USING ERRCODE = '22023';
        END;

        IF JSONB_TYPEOF(v_item -> 'ativo') IS DISTINCT FROM 'boolean' THEN
            RAISE EXCEPTION 'O campo ativo do item % deve ser true ou false.', v_indice
                USING ERRCODE = '22023';
        END IF;

        IF v_nr = ANY(v_nrs_processadas) THEN
            RAISE EXCEPTION 'A NR % aparece mais de uma vez na lista.', v_nr
                USING ERRCODE = '22023';
        END IF;
        v_nrs_processadas := ARRAY_APPEND(v_nrs_processadas, v_nr);

        IF NOT EXISTS (
            SELECT 1 FROM nr_catalogo WHERE codigo_nr = v_nr
        ) THEN
            RAISE EXCEPTION 'A NR % não existe no catálogo.', v_nr
                USING ERRCODE = '22023';
        END IF;

        v_ativo := (v_item ->> 'ativo')::BOOLEAN;

        IF v_ativo THEN
            INSERT INTO cargo_nr (cargo_id, nr_id)
            VALUES (p_id_cargo, v_nr)
            ON CONFLICT (cargo_id, nr_id) DO NOTHING;
        ELSE
            DELETE FROM cargo_nr
            WHERE cargo_id = p_id_cargo
              AND nr_id = v_nr;
        END IF;
    END LOOP;
END;
$$;

COMMENT ON PROCEDURE pr_alterar_cargo_nrs(TEXT, BIGINT, JSONB) IS
'Atualiza as NRs associadas a um cargo. Exige um gestor ativo do mesmo workspace; cada item do array JSON liga a NR quando ativo é true e remove a ligação quando ativo é false. Valida formato, códigos existentes e duplicidades antes de concluir a chamada.';

CREATE OR REPLACE PROCEDURE pr_alterar_unidade_nrs(
