        ELSE
            DELETE FROM unidade_nr
            WHERE unidade_id = p_id_unidade
              AND nr_id = v_nr;
        END IF;
    END LOOP;
END;
$$;

COMMENT ON PROCEDURE pr_alterar_unidade_nrs(TEXT, BIGINT, JSONB) IS
'Atualiza as NRs associadas a uma unidade. Exige um gestor ativo do mesmo workspace; cada item do array JSON liga a NR quando ativo é true e remove a ligação quando ativo é false. Valida formato, códigos existentes e duplicidades.';

