COMMENT ON COLUMN workspace.nome IS 'Nome empresarial ou nome de exibição do workspace.';
COMMENT ON COLUMN workspace.cnpj IS 'CNPJ do workspace, armazenado somente com os 14 dígitos.';

CREATE TABLE cargo (
    id_cargo BIGSERIAL,
    workspace_id BIGINT,
    nome VARCHAR(255),
    ativo BOOLEAN
