                USING ERRCODE = '22023';
        END IF;
        v_nrs_processadas := ARRAY_APPEND(v_nrs_processadas, v_nr);

        IF NOT EXISTS (
            SELECT 1 FROM nr_catalogo WHERE codigo_nr = v_nr
        ) THEN
            RAISE EXCEPTION 'A NR % não existe no catálogo.', v_nr
                USING ERRCODE = '22023';
        END IF;

        v_ativo := (v_item ->> 'ativo')::BOOLEAN;

        IF v_ativo THEN
            INSERT INTO unidade_nr (unidade_id, nr_id)
            VALUES (p_id_unidade, v_nr)
            ON CONFLICT (unidade_id, nr_id) DO NOTHING;
        ELSE
            DELETE FROM unidade_nr
            WHERE unidade_id = p_id_unidade
              AND nr_id = v_nr;
        END IF;
    END LOOP;
END;
$$;

