DROP TRIGGER IF EXISTS trg_ativar_colaborador_apos_firebase_uid ON usuario;
CREATE TRIGGER trg_ativar_colaborador_apos_firebase_uid
BEFORE UPDATE OF firebase_uid ON usuario
FOR EACH ROW
WHEN (
