    AND NEW.firebase_uid IS NOT NULL
    AND NEW.tipo = 'COLABORADOR'
    AND NEW.status = 'PRE_CADASTRADO'
)
EXECUTE FUNCTION fn_ativar_colaborador_apos_firebase_uid();

